[data-ds-root][data-vertical="bithire"][data-tenant][data-tenant="fixture-tenant"] {
  --ds-color-accent: #E2725B;
  --ds-color-accent-100: #FFD1C7;
  --ds-color-accent-200: #FFA491;
  --ds-color-accent-300: #EA816B;
  --ds-color-accent-400: #CE614B;
  --ds-color-accent-50: #FFFBFA;
  --ds-color-accent-500: #AF4530;
  --ds-color-accent-600: #8C2C1A;
  --ds-color-accent-700: #681809;
  --ds-color-accent-800: #430A02;
  --ds-color-accent-900: #1E0401;
  --ds-color-primary: #0F766E;
  --ds-color-primary-100: #B7E9E3;
  --ds-color-primary-200: #8BCEC6;
  --ds-color-primary-300: #63B3AA;
  --ds-color-primary-400: #3F978E;
  --ds-color-primary-50: #F2FFFD;
  --ds-color-primary-500: #1B7B73;
  --ds-color-primary-600: #005F58;
  --ds-color-primary-700: #00433E;
  --ds-color-primary-800: #002925;
  --ds-color-primary-900: #00110F;
  --ds-color-secondary: #8C6D46;
  --ds-color-secondary-100: #EFDAC0;
  --ds-color-secondary-200: #D6BB9A;
  --ds-color-secondary-300: #BB9D77;
  --ds-color-secondary-400: #A08059;
  --ds-color-secondary-50: #FFFBF6;
  --ds-color-secondary-500: #84653F;
  --ds-color-secondary-600: #674C29;
  --ds-color-secondary-700: #4A3417;
  --ds-color-secondary-800: #2E1F0A;
  --ds-color-secondary-900: #130C03;
  --ds-elevation-1: 0 2px 4px rgba(0,0,0,0.08);
  --ds-elevation-2: 0 4px 8px rgba(0,0,0,0.1);
  --ds-elevation-3: 0 8px 16px rgba(0,0,0,0.12);
  --ds-font-family-base: Optima, Candara, 'Noto Sans', sans-serif;
  --ds-font-family-heading: 'Fraunces', Georgia, 'Times New Roman', serif;
  --ds-motion-ambient: subtle;
  --ds-motion-duration-scale: 1.15;
  --ds-motion-intensity: 0.62;
  --ds-radius-button: var(--ds-radius-md, 8px);
  --ds-sidebar-bg: var(--ds-color-bg-secondary);
  --ds-sidebar-item-bg-active: var(--ds-color-primary-100);
  --ds-sidebar-item-bg-hover: var(--ds-color-bg-hover);
  --ds-sidebar-item-color-active: var(--ds-color-primary);
  --ds-sidebar-text: var(--ds-color-text-primary);
  --ds-sidebar-text-muted: var(--ds-color-text-muted);
}
